### Ran Playwright code
```js
// Screenshot viewport and save it as screenshots/night-run.jpg
await page.screenshot({
  path: 'screenshots/night-run.jpg',
  quality: 90,
  scale: 'css',
  type: 'jpeg'
});
```

### Result
{"timer":"00:49","score":"00000","overlay":"overlay hidden"}
### Ran Playwright code
```js
await (async (page) => { await page.keyboard.down('Space'); await page.waitForTimeout(1400); await page.keyboard.up('Space'); return {timer: await page.locator('#timer').innerText(), score: await page.locator('#score').innerText(), overlay: await page.locator('#overlay').getAttribute('class')}; })(page);
```

### Result
{"timer":"01:27","score":"00000","health":"<i class=\"heart\"></i><i class=\"heart\"></i><i class=\"heart\"></i>"}
### Ran Playwright code
```js
await (async (page) => { await page.locator('#pause').click(); await page.locator('#play').click(); await page.keyboard.down('Space'); await page.waitForTimeout(3000); await page.keyboard.up('Space'); return {timer: await page.locator('#timer').innerText(), score: await page.locator('#score').innerText(), health: await page.locator('#health').evaluate(e=>e.innerHTML)}; })(page);
```

